TLM.f("Tempora/Pasc6-5",{"officium":"Feria VI post Octavam Ascensionis","rule":["ex Tempora/Pasc6-0;","ex Tempora/Pasc5-4;","Gloria","no Credo","Suffr=Maria3;Ecclesiæ,Papa;;"],"ruleInherited":["Evangelium non appropriatum","ex Tempora/Pasc5-4;","Gloria","Credo","Gloria","Credo","Prefatio=Asc","Gloria","Credo","Suffr=Maria3;Ecclesiæ,Papa;;"],"fallback":"Tempora/Pasc6-0","from":{"Introitus":"Tempora/Pasc6-0","Oratio":"Tempora/Pasc6-0","Lectio":"Tempora/Pasc6-0","Graduale":"Tempora/Pasc6-0","Evangelium":"Tempora/Pasc6-0","Offertorium":"Tempora/Pasc6-0","Secreta":"Tempora/Pasc6-0","Communio":"Tempora/Pasc6-0","Postcommunio":"Tempora/Pasc6-0","Commemoratio Oratio":"Tempora/Pasc6-0","Commemoratio Secreta":"Tempora/Pasc6-0","Commemoratio Postcommunio":"Tempora/Pasc6-0"},"sections":{"Introitus":[{"k":"ref","la":"Ps 26:7; 26:8; 26:9"},{"k":"text","la":"Exáudi, Dómine, vocem meam, qua clamávi ad te, allelúja: tibi dixit cor meum, quæsívi vultum tuum, vultum tuum, Dómine, requíram: ne avértas fáciem tuam a me, allelúja, allelúja."},{"k":"ref","la":"Ps 26:1"},{"k":"text","la":"Dóminus illuminátio mea et salus mea: quem timébo?"},{"k":"macro","name":"Gloria"},{"k":"text","la":"Exáudi, Dómine, vocem meam, qua clamávi ad te, allelúja: tibi dixit cor meum, quæsívi vultum tuum, vultum tuum, Dómine, requíram: ne avértas fáciem tuam a me, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Omnípotens sempitérne Deus: fac nos tibi semper et devótam gérere voluntátem; et majestáti tuæ sincéro corde servíre."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Petri Apóstoli"},{"k":"ref","la":"1 Pet 4:7-11"},{"k":"text","la":"Caríssimi: Estóte prudéntes et vigiláte in oratiónibus. Ante ómnia autem mútuam in vobismetípsis caritátem contínuam habéntes: quia cáritas óperit multitúdinem peccatórum. Hospitáles ínvicem sine murmuratióne: unusquísque, sicut accépit grátiam, in altérutrum illam administrántes, sicut boni dispensatóres multifórmis grátiæ Dei. Si quis lóquitur, quasi sermónes Dei: si quis minístrat, tamquam ex virtúte, quam adminístrat Deus: ut in ómnibus honorificétur Deus per Jesum Christum, Dóminum nostrum."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 46:9"},{"k":"text","la":"Regnávit Dóminus super omnes gentes: Deus sedet super sedem sanctam suam. Allelúja.","mark":"V"},{"k":"ref","la":"Joannes 14:18"},{"k":"text","la":"Non vos relínquam órphanos: vado, et vénio ad vos, et gaudébit cor vestrum. Allelúja.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 15:26-27; 16:1-4"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Cum vénerit Paráclitus, quem ego mittam vobis a Patre, Spíritum veritátis, qui a Patre procédit, ille testimónium perhibébit de me: et vos testimónium perhibébitis, quia ab inítio mecum estis. Hæc locútus sum vobis, ut non scandalizémini. Absque synagógis fácient vos: sed venit hora, ut omnis, qui intérficit vos, arbitrétur obséquium se præstáre Deo. Et hæc fácient vobis, quia non novérunt Patrem neque me. Sed hæc locútus sum vobis: ut, cum vénerit hora eórum, reminiscámini, quia ego dixi vobis."}],"Offertorium":[{"k":"ref","la":"Ps 46:6"},{"k":"text","la":"Ascéndit Deus in jubilatióne, et Dóminus in voce tubæ, allelúja."}],"Secreta":[{"k":"text","la":"Sacrifícia nos, Dómine, immaculáta puríficent: et méntibus nostris supérnæ grátiæ dent vigórem."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Joannes 17:12-13; 17:15"},{"k":"text","la":"Pater, cum essem cum eis, ego servábam eos, quos dedísti mihi, allelúja: nunc autem ad te vénio: non rogo, ut tollas eos de mundo, sed ut serves eos a malo, allelúja, allelúja."}],"Postcommunio":[{"k":"text","la":"Repléti, Dómine, munéribus sacris: da, quǽsumus; ut in gratiárum semper actióne maneámus."},{"k":"macro","name":"Per Dominum"}],"Commemoratio Oratio":[{"k":"rubric","la":"Pro Octava Ascensionis"},{"k":"text","la":"Concéde, quǽsumus, oninípotens Deus: ut, qui hodiérna die Unigénitum tuum, Redemptórem nostrum, ad cœlos ascendísse crédimus; ipsi quoque mente in cœléstibus habitémus."},{"k":"macro","name":"Per eumdem"}],"Commemoratio Secreta":[{"k":"rubric","la":"Pro Octava Ascensionis"},{"k":"text","la":"Súscipe, Dómine, múnera, quæ pro Fílii tui gloriósa Ascensióne deférimus: et concéde propítius; ut a præséntibus perículis liberémur, et ad vitam perveniámus ætérnam."},{"k":"macro","name":"Per eumdem"}],"Commemoratio Postcommunio":[{"k":"rubric","la":"Pro Octava Ascensionis."},{"k":"text","la":"Præsta nobis, quǽsumus, omnípotens et miséricors Deus: ut, quæ visibílibus mystériis suménda percépimus, invisíbili consequámur efféctu."},{"k":"macro","name":"Per Dominum"}]},"hr":{"12a9e2a0b837e8a0":{"t":"Ps 26, 7, 8 i 9, Ps 26, 1\n(Ps 26, 7, 8 i 9) Usliši, Gospodine, moj glas kojim vapijem k tebi, <i>aleluja</i>.\nTebi govori moje srce; tražim lice tvoje, Gospodine, tvoje lice tražim. Ne skrivaj lica svojega od mene, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 26, 1) Gospodin mi je svjetlo i spas. Koga da se bojim?\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 26, 7, 8 i 9) Usliši, Gospodine, moj glas kojim vapijem k tebi, <i>aleluja</i>.\nTebi govori moje srce; tražim lice tvoje, Gospodine, tvoje lice tražim. Ne skrivaj lica svojega od mene, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Ps. 26, 7-8). Cuj, Gasjpodlne, glas moj, kojim k Tebi vapijem, aleluja; Tebi govori srce moje, Tebe traži lice moje, lice Tvoje, Gospodine, tražim; ne odvrati od mene lica svojega, aleluja, aleluja (Ps. 26, 1). Goispodin je svjetlost moja i Bpa,®enje moje, koga da se bojim? Slava Ocu . . . Cuj, CJospodine . . .","knRef":"Kniewald 1942, str. 334–335 (snimka 168) (OCR)"},"a887abba7210ae3a":{"t":"<i>Pomolimo se</i>.\nSvemogući vječni Bože, daj da ti uvijek budemo odani voljom i tvojemu veličanstvu služimo iskrena srca.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Svemogući, vječni Bože, daj, da Ti vazda budemo i poibožnom voljom odani i da iskrenim srcem služimo Tvojemu veličanstvu, po G. n.","knRef":"Kniewald 1942, str. 334–335 (snimka 168) (OCR)"},"4485b705047348a1":{"t":"1 Pt 4, 7-11\nČitanje Poslanice bl. Petra apostola. Predragi, budite mudri i budni u molitvama. Prije svega pak trajno se ljubite međusobno, jer ljubav oprašta mnoge grijehe. Bez prigovora budite gostoljubivi jedan prema drugome. Kao dobri djelitelji mnogovrsne Božje milosti dajte jedan drugome ono što je tko primio na dar. Ako je tko primio dar govora, neka ga predaje kao riječ Božju. Ako je tko pozvan da poslužuje, neka to radi onom moću koju daje Bog, da se u svemu slavi Bog po našem Gospodinu Isusu Kristu.","kn":"Čitanje poslanice bi. Petra apostola (I, 4, 7-11). Predragi! Budite mudri i budni u molitvama. Prije svega trajno se ljubite među sobom, jer ljubav pokriva mnoštvo grijeha. Budite među sobom gostoljubivi bez prigovora. Kao dobri djelitelji mnogo- vrsne Božje milosti poslužujte jedan drugoga oinim darom, koji je svaki primio. Ako tko ima dar jezika, neka govori kao Božje riječi, ako tko služi, neka služi po moči, koju daje Bog, da se u svemu slavi Bog po Isusu Kristu, Gospodinu našemu.","knRef":"Kniewald 1942, str. 334–335 (snimka 168) (OCR)"},"3555a1814fc15f45":{"t":"Ps 46, 9, Io 14, 18\n<i>Aleluja</i>, <i>aleluja</i>.\n(Ps 46, 9) Gospodin je zavladao svim narodima. Bog sjedi na svome svetom prijestolju, <i>aleluja</i>.\n(Iv 14, 18) Neću vas ostaviti kao sirote. Idem, ali ću opet doći k vama, i radovat će se vaše srce, <i>aleluja</i>.","kn":"Aleluja, aleluja (Ps. 46, 9). Zavlada Gospodin svim narodima; Bog sjedi na prijestolu svetomu svojemu, aleluja. (Iv. 14, 18) Ne ću vas ostaviti sirote, doći ću k vama, i radovat će se srce vaše, aleluja.","knRef":"Kniewald 1942, str. 336–337 (snimka 169) (OCR)"},"247bf5ed1b022976":{"t":"Iv 15, 26-27 i 16, 1-4\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme reče Isus svojim učenicima: Kad dođe Utješitelj, koga ću vam ja poslati od Oca, Duh istine, koji izlazi od Oca, on će svjedočiti o meni. I vi ćete svjedočiti, jer ste od početka sa mnom. Ovo sam vam rekao da se ne smutite. Tjerat će vas iz zbornica. Dapače dolazi vrijeme kad će svaki koji vas ubije misliti da služi Bogu. To će vam činiti, jer ne poznaju ni Oca ni mene. Ovo sam vam iznio zato da se, kad dođe to vrijeme, sjetite da sam vam rekao.","kn":"t Slijedi sveto evanđelje po Ivanu (15, 26-27, 16, 1-4). U ono vrijeme reče Isus svojim učenicima: Kada dođe Utješitelj, kojega ću vam ja poslati od Oca, Duh istine, koji izlazi od Oca, on će svjedočiti o meni. I vi ćete svjedočiti, jer ste od početka sa mnom. To sam vam kazao, da se ne sablaznite, jer će vas goniti iz sinagoga, a ide vrijeme, kad će svaki, koji vas ubije, misliti, da služi Bogu. A to će vam činiti, jer ne poznaju Oca ni mene. Ovo sam vam rekao zato, da se sjetite, da sam vam ja rekao, kada dođe to vrijeme.","knRef":"Kniewald 1942, str. 336–337 (snimka 169) (OCR)"},"95c349320dc6471f":{"t":"Ps 46, 6\nUzlazi Bog uz klicanje i Gospodin uz glas trublje, <i>aleluja</i>.","kn":"(Ps. 46, 6). Uziđe Bog u klicanju, Gospodin uz glas trube. Aleluja.","knRef":"Kniewald 1942, str. 334–335 (snimka 168) (OCR)"},"c9a64c5aed27d7b6":{"t":"Neokaljane žrtve, Gospodine, neka nas očiste i dadu našim dušama snagu višnje milosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":", Neka nas očiste. Gospodine, neoskvrnjene žrtve i neka dadu dušama našim snagu višnje milosti po G. n.","knRef":"Kniewald 1942, str. 336–337 (snimka 169) (OCR)"},"e3481c16f40c8803":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – On se poslije svojeg uskrsnuća svim svojim učenicima javno ukazao i pred njihovim se očima uzdigao na nebo, da nas učini dionicima svoga božanstva. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Predslovlje: Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospodinu našem, jer On se poslije svoga uskrsnuća očito ukazao svim svojim učenicima 1 njima se na očigled uzđignuo na nebo, da tako, po njegovom daru, budemo zajedničari Božanstva Njegova. I toga radi pjevamo pjesmu slave Tvoje s anđelima i B arkanđelima, s prijestolima i s gospodstvima, sa svom silom nebeske vojske bez prestanka govoreći:","knRef":"Kniewald 1942, str. 336–337 (snimka 169) (OCR)"},"6b1b50452428fdbb":{"t":"Iv 17, 12-13 et 15\nOče, dok sam bio s njima, ja sam čuvao one koje si mi dao, <i>aleluja</i>.\nSada dolazim k tebi. Ne molim te da ih uzmeš sa svijeta, nego da ih čuvaš od zla, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Iv. 17, 12, 13, 15). Oče, dok bijah s njima, ja euvah one, koje si mi dao, aleluja, a sad dolazim' k Tebi; ne molim te, da ih uzmeš sa svijeta, nego da ih čuvaš od onoga, koji je zao, aleluja, aleluja.","knRef":"Kniewald 1942, str. 336–337 (snimka 169) (OCR)"},"9b8de3407a193a85":{"t":"<i>Pomolimo se</i>.\nPodaj, molimo, Gospodine, da ti uvijek budemo zahvalni mi koji se nasitismo svetih darova.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Nahranjeni, Gospodine, svetim darovima, molimo, da zagovorom Tvojih svetih uvijek ostanemo zahvalni Tvojoj dobroti,, po G. n.","knRef":"Kniewald 1942, str. 696–697 (snimka 349) (OCR)"}}});
